    fallbackSrc: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600"
  },
  {
    id: 21,
    title: "Botanical Garden 14570",
    category: "Nature",
    filename: "photo-1457089328109-e5d9bd499191.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1465146344425-f00d5f5c8f07?w=600"
  },
  {
    id: 22,
    title: "Golden Hour Valley 14722",
    category: "Nature",
    filename: "photo-1472214103451-9374bd1c798e.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=600"
  },
  {
    id: 23,
    title: "Orange Blossoms 16840",
    category: "Nature",
    filename: "photo-1684087554249-0021c9c85fc9.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1508610048659-a06b669e3321?w=600"
  },
  {
    id: 24,
    title: "Purple Canopy Forest 16939",
    category: "Nature",
    filename: "photo-1693985007521-e08e64770947.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600"
  },
  {
    id: 25,
    title: "Blue Hour Meadow 16950",
    category: "Nature",
    filename: "photo-1695004672476-0c1e8d7a7e79.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=600"
  },
  {
    id: 26,
    title: "Fashion Model premium_16790",
    category: "Fashion",
    filename: "premium_photo-1679064458881-76904cf6d1aa.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=600"
  },
  {
    id: 27,
    title: "Sunset Reflection Ball",
    category: "Nature",
    filename: "Sunset-ball.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1495616811223-4d98c6e9c869?w=600"
  },
  {
    id: 28,
    title: "Geranium Red Flowers",
    category: "Nature",
    filename: "types-of-red-flowers-geranium.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1508610048659-a06b669e3321?w=600"
  },
  {
    id: 29,
    title: "Kathy Karn Wildlife",
    category: "Nature",
    filename: "Wildlife+Photography+by+Kathy+Karn+01.jpg",
    fallbackSrc: "https://images.unsplash.com/photo-1534188753412-3e26d0d618d6?w=600"
  }
];

const PACKAGES = [
  { id: "basic", name: "Basic", price: 150, duration: "2 Hours", features: ["1 Photographer", "15 Edited Photos", "Online Gallery"] },
  { id: "standard", name: "Standard", price: 350, duration: "4 Hours", features: ["1 Photographer", "40 Edited Photos", "Online Gallery", "1 Canvas Print"] },
  { id: "premium", name: "Premium", price: 700, duration: "Full Day", features: ["2 Photographers", "All Edited Photos", "Online Gallery", "Album + Prints"] }
];

// Helper to construct exact public/images path
const getImagePath = (filename) => {
  return process.env.PUBLIC_URL + `/images/${filename}`;
};

export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [favorites, setFavorites] = useState(() => {
    const saved = localStorage.getItem("fav_photos");
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedCategory, setSelectedCategory] = useState("All");
  const [activeLightbox, setActiveLightbox] = useState(null);

  // Login System States
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [runConfetti, setRunConfetti] = useState(false);

  // Theme State (Dark mode enabled by default)
  const [theme, setTheme] = useState(() => localStorage.getItem("theme") || "dark");

  // 2. Smooth Scrolling Effect
  useEffect(() => {
    // Add smooth scrolling style directly to HTML tag
    document.documentElement.style.scrollBehavior = "smooth";
    return () => {
      document.documentElement.style.scrollBehavior = "auto";
    };
  }, []);

  useEffect(() => {
    localStorage.setItem("theme", theme);
    document.body.className = theme;
  }, [theme]);

  useEffect(() => {
    localStorage.setItem("fav_photos", JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id) => {
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  // 3. Login/Logout Logic with Confetti
  const handleLoginSubmit = (e) => {
    e.preventDefault();
    // Simulate login for demonstration
    if (loginForm.username && loginForm.password) {
      setIsLoggedIn(true);
      setShowLoginModal(false);
      setRunConfetti(true); // Start sprinkles effect
      // Stop confetti after 5 seconds
      setTimeout(() => setRunConfetti(false), 5000); 
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab("home");
  };

  const filteredImages = GALLERY_IMAGES.filter((img) =>
    selectedCategory === "All" || img.category === selectedCategory
  );

  const displayedImages = activeTab === "favorites"
    ? GALLERY_IMAGES.filter((img) => favorites.includes(img.id))
    : filteredImages;

  return (
    <div className={`app-container ${theme}`}>
      {/* Run Confetti sprinkles on victory */}
      {runConfetti && (
        <Confetti
          width={window.innerWidth}
          height={window.innerHeight}
          recycle={false} // Confetti stops after one burst
          numberOfPieces={400}
        />
      )}

      {/* Sticky Navbar */}
      <nav className="navbar">
        <div className="nav-brand"><span>📷</span> SHUTTER STORIES</div>
        <ul className="nav-links">
          {["home", "gallery", "packages", "favorites"].map((tab) => (
            <li key={tab}>
              <button
                className={activeTab === tab ? "active" : ""}
                onClick={() => setActiveTab(tab)}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === "favorites" ? `(${favorites.length})` : ""}
              </button>
            </li>
          ))}
          <li>
            {isLoggedIn ? (
              <button className="auth-btn logout-btn" onClick={handleLogout}>Logout</button>
            ) : (
              <button className="auth-btn login-btn" onClick={() => setShowLoginModal(true)}>Login</button>
            )}
          </li>
          <li>
            <button className="theme-toggle" onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>
              {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
            </button>
          </li>
        </ul>
      </nav>

      {/* Hero Section */}
      {activeTab === "home" && (
        <section className="hero-section">
          <div className="hero-backdrop">
            <img
              src={getImagePath("hero-bg.jpg")}
              alt="Photographer hero backdrop"
              onError={(e) => {
                e.target.onerror = null;
                // If local hero-bg fails, fallback to online background
                e.target.src = "https://images.unsplash.com/photo-1542038784456-1ea8e935640e?w=1200";
              }}
            />
            <div className="hero-overlay"></div>
          </div>
          <div className="hero-content">
            <h1>Capturing Moments</h1>
            <p>Professional photography services for the stories that matter.</p>
            <button className="btn-primary" onClick={() => setActiveTab("gallery")}>View Portfolio</button>
          </div>
        </section>
      )}

      {/* Portfolio / Favorites Gallery */}
      {(activeTab === "gallery" || activeTab === "favorites") && (
        <section className="gallery-section">
          <h2>{activeTab === "favorites" ? "Your Favorites" : "Portfolio Gallery"}</h2>

          {activeTab !== "favorites" && (
            <div className="filter-bar">
              {CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  className={selectedCategory === cat ? "filter-btn active" : "filter-btn"}
                  onClick={() => setSelectedCategory(cat)}
                >
                  {cat}
                </button>
              ))}
            </div>
          )}

          <div className="gallery-grid">
            {displayedImages.length > 0 ? displayedImages.map((img) => (
              <div className="gallery-card" key={img.id}>
                <div className="img-wrapper">
                  <img
                    src={getImagePath(img.filename)}
                    alt={img.title}
                    onError={(e) => {
                      e.target.onerror = null;
                      // Show exact fallback link if direct file missing
                      e.target.src = img.fallbackSrc;
                    }}
                    onClick={() => setActiveLightbox(img)}
                  />
                </div>
                <div className="card-info">
                  <h4>{img.title}</h4>
                  <button className="fav-btn" onClick={() => toggleFavorite(img.id)}>
                    {favorites.includes(img.id) ? "❤️" : "🤍"}
                  </button>
                </div>
              </div>
            )) : <p className="no-data">No favorites yet.</p>}
          </div>
        </section>
      )}

      {/* Packages Section */}
      {activeTab === "packages" && (
        <section className="packages-section">
          <h2>Pricing Packages</h2>
          <div className="packages-grid">
            {PACKAGES.map((pkg) => (
              <div key={pkg.id} className="package-card">
                <h3>{pkg.name}</h3>
                <p className="price">${pkg.price}</p>
                <ul>
                  {pkg.features.map((feat, idx) => <li key={idx}>✓ {feat}</li>)}
                </ul>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Login Modal */}
      {showLoginModal && (
        <div className="auth-overlay" onClick={() => setShowLoginModal(false)}>
          <div className="auth-card" onClick={(e) => e.stopPropagation()}>
            <button className="close-modal" onClick={() => setShowLoginModal(false)}>✕</button>
            <h3>Sign In</h3>
            <form onSubmit={handleLoginSubmit}>
              <input
                type="text"
                placeholder="Username (e.g., kootay)"
                required
                value={loginForm.username}
                onChange={(e) => setLoginForm({ ...loginForm, username: e.target.value })}
              />
              <input
                type="password"
                placeholder="Password"
                required
                value={loginForm.password}
                onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })}
              />
              <button type="submit" className="btn-primary">Confirm Login</button>
            </form>
          </div>
        </div>
      )}

      {/* Image Lightbox Modal */}
      {activeLightbox && (
        <div className="lightbox-overlay" onClick={() => setActiveLightbox(null)}>
          <div className="lightbox-content">
            <button className="close-btn" onClick={() => setActiveLightbox(null)}>✕</button>
            <img
              src={getImagePath(activeLightbox.filename)}
              alt={activeLightbox.title}
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = activeLightbox.fallbackSrc;
              }}
            />
          </div>
        </div>
      )}

      {/* 5. Footer with Left Social Icons */}
      <footer className="footer">
        <div className="footer-left">
          <a href="https://wa.me/1234567890" target="_blank" rel="noopener noreferrer">
            <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="WhatsApp" className="social-icon" />
          </a>
          <a href="https://www.tiktok.com/@yourusername" target="_blank" rel="noopener noreferrer">
            <img src="https://upload.wikimedia.org/wikipedia/en/a/a9/TikTok_logo.svg" alt="TikTok" className="social-icon" />
          </a>
          <a href="https://www.instagram.com/yourusername" target="_blank" rel="noopener noreferrer">
            <img src="https://upload.wikimedia.org/wikipedia/commons/e/e7/Instagram_logo_2016.svg" alt="Instagram" className="social-icon" />
          </a>
        </div>
        <div className="footer-center">
          <p>© 2026 Shutter Stories Photography. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}
